<?php

$pass = 0;
$fail = 0;

function assert_true($cond, $msg) {
    global $pass, $fail;
    if ($cond) {
        echo "  PASS: $msg\n";
        $pass++;
    } else {
        echo "  FAIL: $msg\n";
        $fail++;
    }
}

function assert_same($actual, $expected, $msg) {
    assert_true(
        $actual === $expected,
        "$msg (got " . var_export($actual, true) . ", expected " . var_export($expected, true) . ")"
    );
}

function assert_throws(callable $fn, string $contains, string $msg): void {
    try {
        $fn();
        assert_true(false, $msg . ' (no exception thrown)');
    } catch (Throwable $e) {
        assert_true(str_contains($e->getMessage(), $contains), $msg . ' (' . $e->getMessage() . ')');
    }
}

function run_merge_cli(array $args): array {
    $script = dirname(__DIR__, 2) . '/scripts/cow/merge.php';
    $command = array_map('escapeshellarg', array_merge([PHP_BINARY, $script], $args));
    exec(implode(' ', $command) . ' 2>&1', $output, $status);
    return [
        'status' => $status,
        'output' => implode("\n", $output) . ($output === [] ? '' : "\n"),
    ];
}

function run_merge_cli_env(array $args, array $env): array {
    $script = dirname(__DIR__, 2) . '/scripts/cow/merge.php';
    $base_env = getenv();
    if (!is_array($base_env)) {
        $base_env = [];
    }
    $pipes = [];
    $process = proc_open(
        array_merge([PHP_BINARY, $script], $args),
        [
            1 => ['pipe', 'w'],
            2 => ['pipe', 'w'],
        ],
        $pipes,
        null,
        array_merge($base_env, $env)
    );
    if (!is_resource($process)) {
        throw new RuntimeException('failed to start merge CLI subprocess');
    }
    $stdout = stream_get_contents($pipes[1]);
    $stderr = stream_get_contents($pipes[2]);
    fclose($pipes[1]);
    fclose($pipes[2]);
    return [
        'status' => proc_close($process),
        'output' => (is_string($stdout) ? $stdout : '') . (is_string($stderr) ? $stderr : ''),
    ];
}

function remove_tree(string $path): void {
    if (!file_exists($path) && !is_link($path)) {
        return;
    }
    if (is_file($path) || is_link($path)) {
        unlink($path);
        return;
    }
    $it = new RecursiveIteratorIterator(
        new RecursiveDirectoryIterator($path, RecursiveDirectoryIterator::SKIP_DOTS),
        RecursiveIteratorIterator::CHILD_FIRST
    );
    foreach ($it as $entry) {
        $entry->isDir() && !$entry->isLink() ? rmdir($entry->getPathname()) : unlink($entry->getPathname());
    }
    rmdir($path);
}

function copy_tree_for_test(string $source, string $dest): void {
    mkdir($dest, 0777, true);
    $it = new RecursiveIteratorIterator(
        new RecursiveDirectoryIterator($source, RecursiveDirectoryIterator::SKIP_DOTS),
        RecursiveIteratorIterator::SELF_FIRST
    );
    foreach ($it as $entry) {
        $target = $dest . '/' . str_replace(DIRECTORY_SEPARATOR, '/', substr($entry->getPathname(), strlen($source) + 1));
        if ($entry->isLink()) {
            if (!is_dir(dirname($target))) {
                mkdir(dirname($target), 0777, true);
            }
            $link_target = readlink($entry->getPathname());
            if (!is_string($link_target) || !symlink($link_target, $target)) {
                throw new RuntimeException('failed to copy test symlink: ' . $entry->getPathname());
            }
            continue;
        }
        if ($entry->isDir()) {
            if (!is_dir($target)) {
                mkdir($target, 0777, true);
            }
            continue;
        }
        if (!is_dir(dirname($target))) {
            mkdir(dirname($target), 0777, true);
        }
        copy($entry->getPathname(), $target);
    }
}

function write_test_file(string $path, string $contents): void {
    if (!is_dir(dirname($path))) {
        mkdir(dirname($path), 0777, true);
    }
    file_put_contents($path, $contents);
}

function create_test_symlink(string $target, string $link): void {
    if (!is_dir(dirname($link))) {
        mkdir(dirname($link), 0777, true);
    }
    if ((file_exists($link) || is_link($link)) && !unlink($link)) {
        throw new RuntimeException("failed to replace test symlink: $link");
    }
    if (!symlink($target, $link)) {
        throw new RuntimeException("failed to create test symlink: $link");
    }
}

function open_db(string $path): SQLite3 {
    $db = new SQLite3($path);
    $db->busyTimeout(5000);
    return $db;
}

function create_base_db(string $path): void {
    $db = open_db($path);
    $db->exec('CREATE TABLE wp_posts (ID INTEGER PRIMARY KEY AUTOINCREMENT, post_title TEXT, post_content TEXT, post_status TEXT)');
    $db->exec('CREATE TABLE wp_options (option_id INTEGER PRIMARY KEY AUTOINCREMENT, option_name TEXT UNIQUE, option_value TEXT, autoload TEXT)');
    $db->exec('CREATE TABLE plugin_items (item_id TEXT PRIMARY KEY, label TEXT, value TEXT)');
    $db->exec('CREATE TABLE plugin_keyless (label TEXT, value TEXT)');
    $db->exec("INSERT INTO wp_posts (ID, post_title, post_content, post_status) VALUES (1, 'Base title', 'Base content', 'draft')");
    $db->exec("INSERT INTO wp_options (option_id, option_name, option_value, autoload) VALUES (1, 'theme_mods_test', 'a:1:{s:5:\"color\";s:4:\"blue\";}', 'yes')");
    $db->exec("INSERT INTO plugin_items (item_id, label, value) VALUES ('alpha', 'Alpha', 'base')");
    $db->exec("INSERT INTO plugin_keyless (label, value) VALUES ('Base keyless', 'base')");
    $db->close();
}

function scalar(string $db_path, string $sql): mixed {
    $db = open_db($db_path);
    $value = $db->querySingle($sql);
    $db->close();
    return $value;
}

function column_type(string $db_path, string $table, string $column): ?string {
    $db = open_db($db_path);
    $res = $db->query('PRAGMA table_info("' . str_replace('"', '""', $table) . '")');
    while ($row = $res->fetchArray(SQLITE3_ASSOC)) {
        if ((string)$row['name'] === $column) {
            $type = (string)$row['type'];
            $db->close();
            return $type;
        }
    }
    $db->close();
    return null;
}

define('FORKPRESS_COW_MERGE_TESTS', true);
require_once __DIR__ . '/../../scripts/cow/merge.php';

echo "=== COW generic SQLite merge ===\n";

$tmp = sys_get_temp_dir() . '/forkpress-cow-merge-' . getmypid() . '-' . bin2hex(random_bytes(4));
mkdir($tmp, 0777, true);
$metadata = $tmp . '/.forkpress/cow/merge/metadata.sqlite';

try {
    $base = $tmp . '/base.sqlite';
    $source = $tmp . '/source.sqlite';
    $target = $tmp . '/target.sqlite';
    create_base_db($base);
    copy($base, $source);
    copy($base, $target);

    $db = open_db($source);
    $db->exec("UPDATE wp_posts SET post_content = 'Source content' WHERE ID = 1");
    $db->exec("INSERT INTO wp_posts (ID, post_title, post_content, post_status) VALUES (2, 'Source-only post', 'Created on source', 'publish')");
    $db->exec("UPDATE plugin_items SET value = 'source plugin value' WHERE item_id = 'alpha'");
    $db->close();

    $db = open_db($target);
    $db->exec("UPDATE wp_posts SET post_status = 'publish' WHERE ID = 1");
    $db->close();

    $result = cow_merge_databases($base, $source, $target, $metadata, 'feature', 'main');
    assert_same($result['status'], 'completed', 'independent row and cell merge completes cleanly');
    assert_same(scalar($target, "SELECT post_content FROM wp_posts WHERE ID = 1"), 'Source content', 'source cell change is applied');
    assert_same(scalar($target, "SELECT post_status FROM wp_posts WHERE ID = 1"), 'publish', 'target cell change is preserved');
    assert_same(scalar($target, "SELECT post_title FROM wp_posts WHERE ID = 2"), 'Source-only post', 'source-only row is inserted');
    assert_same(scalar($target, "SELECT value FROM plugin_items WHERE item_id = 'alpha'"), 'source plugin value', 'plugin table with explicit PK merges generically');
    assert_true(file_exists($metadata), 'merge metadata database is created outside the WordPress DB');
    assert_same(
        (int)scalar($metadata, "SELECT COUNT(*) FROM merge_decisions WHERE table_name = 'wp_posts' AND column_name = 'post_status' AND decision = 'target-kept'"),
        1,
        'independent target cell preservation is auditable'
    );

    $volatile_base = $tmp . '/volatile-usermeta-base.sqlite';
    $volatile_source = $tmp . '/volatile-usermeta-source.sqlite';
    $volatile_target = $tmp . '/volatile-usermeta-target.sqlite';
    $volatile_metadata = $tmp . '/.forkpress/cow/merge/volatile-usermeta-metadata.sqlite';
    foreach ([$volatile_base, $volatile_source, $volatile_target] as $path) {
        $db = open_db($path);
        $db->exec('CREATE TABLE wp_posts (ID INTEGER PRIMARY KEY AUTOINCREMENT, post_title TEXT, post_content TEXT, post_status TEXT)');
        $db->exec('CREATE TABLE wp_usermeta (umeta_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, meta_key TEXT NOT NULL, meta_value TEXT NOT NULL)');
        $db->exec("INSERT INTO wp_posts (ID, post_title, post_content, post_status) VALUES (1, 'Shared page', 'Base content', 'draft')");
        $db->exec("INSERT INTO wp_usermeta (umeta_id, user_id, meta_key, meta_value) VALUES (16, 1, 'session_tokens', 'base-token')");
        $db->close();
    }
    $db = open_db($volatile_source);
    $db->exec("UPDATE wp_posts SET post_content = 'Source page content' WHERE ID = 1");
    $db->exec("UPDATE wp_usermeta SET meta_value = 'source-token' WHERE umeta_id = 16");
    $db->exec("INSERT INTO wp_usermeta (umeta_id, user_id, meta_key, meta_value) VALUES (17, 2, 'session_tokens', 'source-only-token')");
    $db->close();
    $db = open_db($volatile_target);
    $db->exec("UPDATE wp_posts SET post_status = 'publish' WHERE ID = 1");
    $db->exec("UPDATE wp_usermeta SET meta_value = 'target-token' WHERE umeta_id = 16");
    $db->close();
    $volatile_result = cow_merge_databases($volatile_base, $volatile_source, $volatile_target, $volatile_metadata, 'feature-volatile-usermeta', 'main');
    assert_same($volatile_result['status'], 'completed', 'branch-local WordPress session tokens do not force a review conflict');
    assert_same(scalar($volatile_target, "SELECT post_content FROM wp_posts WHERE ID = 1"), 'Source page content', 'content changes still merge while session tokens are ignored');
    assert_same(scalar($volatile_target, "SELECT post_status FROM wp_posts WHERE ID = 1"), 'publish', 'target content changes are preserved while session tokens are ignored');
    assert_same(scalar($volatile_target, "SELECT meta_value FROM wp_usermeta WHERE umeta_id = 16"), 'target-token', 'target WordPress session token remains branch-local');
    assert_same((int)scalar($volatile_target, "SELECT COUNT(*) FROM wp_usermeta WHERE umeta_id = 17"), 0, 'source-only WordPress session token is not imported');
    assert_same(
        (int)scalar($volatile_metadata, "SELECT COUNT(*) FROM merge_conflicts WHERE table_name = 'wp_usermeta'"),
        0,
        'volatile WordPress session token policy records no usermeta conflicts'
    );
    assert_true(
        (int)scalar($volatile_metadata, "SELECT COUNT(*) FROM merge_decisions WHERE table_name = 'wp_usermeta' AND decision = 'target-kept' AND reason LIKE '%session_tokens%'") >= 2,
        'volatile WordPress session token skips remain auditable'
    );

    $rollback_base = $tmp . '/rollback-base.sqlite';
    $rollback_source = $tmp . '/rollback-source.sqlite';
    $rollback_target = $tmp . '/rollback-target.sqlite';
    $rollback_metadata = $tmp . '/.forkpress/cow/merge/rollback-metadata.sqlite';
    foreach ([$rollback_base, $rollback_source, $rollback_target] as $path) {
        $db = open_db($path);
        $db->exec('CREATE TABLE plugin_z_rollback_rows (id INTEGER PRIMARY KEY, value TEXT)');
        $db->exec("INSERT INTO plugin_z_rollback_rows (id, value) VALUES (1, 'base')");
        $db->close();
    }
    $db = open_db($rollback_source);
    $db->exec('CREATE TABLE plugin_a_keyless_staged (label TEXT, value TEXT)');
    $db->exec("INSERT INTO plugin_a_keyless_staged (rowid, label, value) VALUES (17, 'staged', 'source')");
    $db->exec("UPDATE plugin_z_rollback_rows SET value = 'source' WHERE id = 1");
    $db->close();
    $db = open_db($rollback_target);
    $db->exec(
        "CREATE TRIGGER plugin_z_rollback_guard BEFORE UPDATE ON plugin_z_rollback_rows " .
        "BEGIN SELECT RAISE(ROLLBACK, 'rollback trigger'); END"
    );
    $db->close();
    assert_throws(
        fn() => cow_merge_databases($rollback_base, $rollback_source, $rollback_target, $rollback_metadata, 'feature-rollback', 'main'),
        'failed to commit target database transaction',
        'whole-merge target rollback is surfaced as a failed merge'
    );
    assert_same(
        (int)scalar($rollback_target, "SELECT COUNT(*) FROM sqlite_master WHERE type = 'table' AND name = 'plugin_a_keyless_staged'"),
        0,
        'whole-merge target rollback removes earlier staged source-added tables'
    );
    assert_same(scalar($rollback_target, 'SELECT value FROM plugin_z_rollback_rows WHERE id = 1'), 'base', 'whole-merge target rollback preserves pre-merge row state');
    assert_same(
        (int)scalar($rollback_metadata, "SELECT COUNT(*) FROM merge_runs WHERE source_branch = 'feature-rollback' AND status = 'failed' AND failure_reason LIKE 'failed to commit target database transaction%'"),
        1,
        'failed whole-merge run remains auditable after metadata rollback'
    );
    assert_same((int)scalar($rollback_metadata, 'SELECT COUNT(*) FROM merge_decisions'), 0, 'failed whole-merge rollback discards staged decision metadata');
    assert_same((int)scalar($rollback_metadata, 'SELECT COUNT(*) FROM merge_conflicts'), 0, 'failed whole-merge rollback discards staged conflict metadata');
    assert_same((int)scalar($rollback_metadata, 'SELECT COUNT(*) FROM merge_row_identities'), 0, 'failed whole-merge rollback discards staged no-primary-key sidecars');

    $merge_begin_base = $tmp . '/merge-begin-base.sqlite';
    $merge_begin_source = $tmp . '/merge-begin-source.sqlite';
    $merge_begin_target = $tmp . '/merge-begin-target.sqlite';
    $merge_begin_metadata = $tmp . '/.forkpress/cow/merge/merge-begin-metadata.sqlite';
    create_base_db($merge_begin_base);
    copy($merge_begin_base, $merge_begin_source);
    copy($merge_begin_base, $merge_begin_target);
    $db = open_db($merge_begin_source);
    $db->exec("UPDATE wp_posts SET post_content = 'Source begin rollback content' WHERE ID = 1");
    $db->close();
    $GLOBALS['cow_merge_test_hooks']['before_sqlite_exec'] = [
        static function (SQLite3 $db, string $sql, string $message): void {
            if ($sql === 'BEGIN IMMEDIATE' && $message === 'failed to start merge metadata transaction') {
                throw new RuntimeException('forced merge metadata begin failure');
            }
        },
    ];
    $merge_begin_failure_message = null;
    try {
        cow_merge_databases(
            $merge_begin_base,
            $merge_begin_source,
            $merge_begin_target,
            $merge_begin_metadata,
            'feature-merge-begin-rollback',
            'main'
        );
    } catch (Throwable $e) {
        $merge_begin_failure_message = $e->getMessage();
    } finally {
        unset($GLOBALS['cow_merge_test_hooks']['before_sqlite_exec']);
    }
    assert_true($merge_begin_failure_message !== null && str_contains($merge_begin_failure_message, 'forced merge metadata begin failure'), 'direct DB merge metadata begin failure is surfaced to the caller');
    assert_same(scalar($merge_begin_target, "SELECT post_content FROM wp_posts WHERE ID = 1"), 'Base content', 'direct DB merge metadata begin failure rolls back the opened target transaction');
    assert_same(
        (int)scalar($merge_begin_metadata, "SELECT COUNT(*) FROM merge_runs WHERE source_branch = 'feature-merge-begin-rollback' AND status = 'failed'"),
        1,
        'direct DB merge metadata begin failure leaves an auditable failed run'
    );
    assert_same((int)scalar($merge_begin_metadata, 'SELECT COUNT(*) FROM merge_decisions'), 0, 'direct DB merge metadata begin failure records no decisions');
    assert_same((int)scalar($merge_begin_metadata, 'SELECT COUNT(*) FROM merge_conflicts'), 0, 'direct DB merge metadata begin failure records no conflicts');

    $schema_read_base = $tmp . '/schema-read-base.sqlite';
    $schema_read_source = $tmp . '/schema-read-source.sqlite';
    $schema_read_target = $tmp . '/schema-read-target.sqlite';
    $schema_read_metadata = $tmp . '/.forkpress/cow/merge/schema-read-metadata.sqlite';
    create_base_db($schema_read_base);
    copy($schema_read_base, $schema_read_source);
    copy($schema_read_base, $schema_read_target);
    $db = open_db($schema_read_source);
    $db->exec("UPDATE wp_posts SET post_content = 'Source schema read content' WHERE ID = 1");
    $db->close();
    $GLOBALS['cow_merge_test_hooks']['before_sqlite_query'] = [
        static function (SQLite3 $db, string $sql, string $message): void {
            if ($message === 'failed to read table schema map') {
                throw new RuntimeException('forced table schema map read failure');
            }
        },
    ];
    assert_throws(
        fn() => cow_merge_databases(
            $schema_read_base,
            $schema_read_source,
            $schema_read_target,
            $schema_read_metadata,
            'feature-schema-read-rollback',
