    assert_same((int)scalar($metadata, "SELECT COUNT(*) FROM merge_decisions WHERE table_name = '__files__' AND decision = 'source-applied' AND row_identity = '$source_new_file_identity' AND reason = 'source added filesystem path and target did not have it' AND target_payload IS NULL"), 1, 'source-only filesystem addition records an empty target payload');
