    assert_same((int)scalar($metadata, "SELECT COUNT(*) FROM merge_decisions WHERE table_name = '__files__' AND decision = 'source-applied' AND row_identity = '$source_changed_file_identity' AND reason = 'source changed filesystem path and target did not change it' AND source_payload = '$source_changed_file_payload' AND chosen_payload = '$source_changed_file_payload' AND target_payload = '$unchanged_target_file_payload'"), 1, 'source-only filesystem file change records source, chosen, and unchanged target payloads');
    assert_same((int)scalar($metadata, "SELECT COUNT(*) FROM merge_decisions WHERE table_name = '__files__' AND decision = 'source-applied' AND row_identity = '$source_changed_file_identity' AND reason = 'source changed filesystem path and target did not change it' AND base_payload = '$unchanged_target_file_payload' AND source_payload = '$source_changed_file_payload' AND target_payload = '$unchanged_target_file_payload' AND chosen_payload = '$source_changed_file_payload'"), 1, 'source-only filesystem file change records base and unchanged target payloads');
    assert_same((int)scalar($metadata, "SELECT COUNT(*) FROM merge_decisions WHERE table_name = '__files__' AND decision = 'source-applied' AND row_identity = '$source_empty_dir_identity' AND reason = 'source added filesystem directory and target did not have it' AND target_payload IS NULL"), 1, 'source-only filesystem directory addition records an empty target payload');
