        $block_id = (int)$graph['block_id'];
        $attachment_id = (int)$graph['attachment_id'];
        $comment_id = (int)$graph['comment_id'];
        $reply_comment_id = (int)$graph['reply_comment_id'];
        $menu_item_id = (int)$graph['menu_item_id'];
