                    'field' => 'graph_serialized.file_path',
                    'missing_file_path' => $file_path,
                ],
            ];
        }
    }
}
echo json_encode([
    'status' => $findings ? 'conflicts' : 'valid',
    'findings' => $findings,
], JSON_UNESCAPED_SLASHES);
